-- User-owned Vault state. All SQL runs in the original Identity/Audit transaction.
CREATE TABLE rss_da.vault_epochs (tenant_id uuid PRIMARY KEY, incarnation uuid NOT NULL DEFAULT gen_random_uuid());
ALTER TABLE rss_da.vault_epochs ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vault_epochs FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vault_epochs FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vault_epochs USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid);
GRANT SELECT,INSERT ON rss_da.vault_epochs TO da_identity_runtime;
CREATE TABLE rss_da.vaults (tenant_id uuid NOT NULL, owner text NOT NULL, id uuid NOT NULL, recovery_key text NOT NULL, root_envelope text NOT NULL, incarnation uuid NOT NULL, revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0), PRIMARY KEY(tenant_id,owner));
ALTER TABLE rss_da.vaults ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vaults FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vaults FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vaults USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true)) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true));
GRANT SELECT,INSERT,UPDATE,DELETE ON rss_da.vaults TO da_identity_runtime;
CREATE TABLE rss_da.vault_devices (tenant_id uuid NOT NULL, owner text NOT NULL, id uuid NOT NULL, incarnation uuid NOT NULL, public_key text NOT NULL, active boolean NOT NULL, PRIMARY KEY(tenant_id,owner,id));
ALTER TABLE rss_da.vault_devices ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vault_devices FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vault_devices FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vault_devices USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true)) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true));
GRANT SELECT,INSERT,UPDATE,DELETE ON rss_da.vault_devices TO da_identity_runtime;
CREATE TABLE rss_da.vault_entries (tenant_id uuid NOT NULL, owner text NOT NULL, id uuid NOT NULL, revision bigint NOT NULL CHECK(revision>0), ciphertext text, PRIMARY KEY(tenant_id,owner,id));
ALTER TABLE rss_da.vault_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vault_entries FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vault_entries FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vault_entries USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true)) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true));
GRANT SELECT,INSERT,UPDATE,DELETE ON rss_da.vault_entries TO da_identity_runtime;
CREATE TABLE rss_da.vault_challenges (tenant_id uuid NOT NULL, owner text NOT NULL, nonce uuid NOT NULL, incarnation uuid NOT NULL, document jsonb NOT NULL, expires_at bigint NOT NULL, PRIMARY KEY(tenant_id,owner,nonce));
ALTER TABLE rss_da.vault_challenges ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vault_challenges FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vault_challenges FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vault_challenges USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true)) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true));
GRANT SELECT,INSERT,UPDATE,DELETE ON rss_da.vault_challenges TO da_identity_runtime;
CREATE TABLE rss_da.vault_receipts (tenant_id uuid NOT NULL, owner text NOT NULL, operation uuid NOT NULL, incarnation uuid NOT NULL, device uuid NOT NULL, control boolean NOT NULL, digest text NOT NULL, document jsonb NOT NULL, PRIMARY KEY(tenant_id,owner,incarnation,operation));
ALTER TABLE rss_da.vault_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE rss_da.vault_receipts FORCE ROW LEVEL SECURITY;
REVOKE ALL ON rss_da.vault_receipts FROM PUBLIC;
CREATE POLICY isolation ON rss_da.vault_receipts USING (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true)) WITH CHECK (tenant_id = nullif(current_setting('rss.tenant_id',true),'')::uuid AND owner = current_setting('rss.vault_owner',true));
GRANT SELECT,INSERT,UPDATE,DELETE ON rss_da.vault_receipts TO da_identity_runtime;
